package com.salim.taxilog

import java.io.ByteArrayOutputStream
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter
import java.util.Locale
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

/**
 * Writes a real, styled .xlsx file (opens in Excel, Google Sheets, WPS) with no
 * third-party library: the workbook XML is generated by hand and zipped.
 */
object XlsxExporter {

    // ---- cell style ids (index into cellXfs below) ----
    private const val S_TITLE = 1
    private const val S_SUBTITLE = 2
    private const val S_HEADER = 3
    private const val S_TEXT = 4
    private const val S_TEXT_Z = 5
    private const val S_AMT = 6
    private const val S_AMT_Z = 7
    private const val S_CARD_LABEL = 8
    private const val S_CARD_VALUE = 9
    private const val S_CARD_AMT = 10
    private const val S_DAY_LABEL = 11
    private const val S_DAY_AMT = 12
    private const val S_GRAND_LABEL = 13
    private const val S_GRAND_AMT = 14
    private const val S_INCL = 15
    private const val S_INCL_Z = 16
    private const val S_SECTION = 17
    private const val S_TEXT_C = 18
    private const val S_TEXT_C_Z = 19
    private const val S_PCT = 20
    private const val S_PCT_Z = 21
    private const val S_FOOT = 22
    private const val S_GRAND_C = 23

    private class Cell(val v: Any?, val s: Int)

    private class Sheet(val name: String) {
        val rows = sortedMapOf<Int, MutableMap<Int, Cell>>()
        val merges = mutableListOf<String>()
        val widths = sortedMapOf<Int, Double>()
        val heights = mutableMapOf<Int, Double>()
        var freezeRow = 0

        fun set(r: Int, c: Int, v: Any?, s: Int) {
            rows.getOrPut(r) { sortedMapOf() }[c] = Cell(v, s)
        }

        /** Merge r,c1..c2 and give every cell in it the same style (keeps borders/fills intact). */
        fun merge(r: Int, c1: Int, c2: Int, v: Any?, s: Int) {
            for (c in c1..c2) set(r, c, if (c == c1) v else null, s)
            if (c2 > c1) merges += "${ref(r, c1)}:${ref(r, c2)}"
        }
    }

    private fun col(c: Int): String {
        var n = c
        val sb = StringBuilder()
        while (n > 0) {
            val m = (n - 1) % 26
            sb.insert(0, ('A' + m))
            n = (n - 1) / 26
        }
        return sb.toString()
    }

    private fun ref(r: Int, c: Int) = "${col(c)}$r"

    private fun esc(s: String) = s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
        .replace("\"", "&quot;").filter { it == '\n' || it == '\t' || it >= ' ' }

    fun build(d: ReportData): ByteArray {
        val trips = tripsSheet(d)
        val summary = summarySheet(d)
        val sheets = listOf(trips, summary)

        val out = ByteArrayOutputStream()
        ZipOutputStream(out).use { zip ->
            fun put(name: String, body: String) {
                zip.putNextEntry(ZipEntry(name))
                zip.write(body.toByteArray(Charsets.UTF_8))
                zip.closeEntry()
            }
            put("[Content_Types].xml", contentTypes(sheets.size))
            put("_rels/.rels", ROOT_RELS)
            put("xl/workbook.xml", workbook(sheets))
            put("xl/_rels/workbook.xml.rels", workbookRels(sheets.size))
            put("xl/styles.xml", STYLES)
            sheets.forEachIndexed { i, s -> put("xl/worksheets/sheet${i + 1}.xml", sheetXml(s)) }
        }
        return out.toByteArray()
    }

    // ------------------------------------------------------------------ sheets

    private fun tripsSheet(d: ReportData): Sheet {
        val s = Sheet("Trips")
        // A: margin, B Date, C Site, D From, E To, F Amount, G Personnel, H Paid By
        listOf(2.5, 15.0, 20.0, 18.0, 18.0, 15.0, 19.0, 13.0).forEachIndexed { i, w -> s.widths[i + 1] = w }
        val first = 2
        val last = 8

        s.heights[2] = 34.0
        s.merge(2, first, last, d.title, S_TITLE)
        s.heights[3] = 18.0
        s.merge(3, first, last, "Operational Field Log & Reimbursement Summary  •  ${d.rangeLabel}", S_SUBTITLE)

        // summary cards on rows 5 (label) / 6 (value)
        val cards = mutableListOf<Triple<String, Any, Boolean>>()
        cards += Triple("TOTAL EXPENSES", d.total, true)
        d.paidBy.take(4).forEach { (p, v) -> cards += Triple("${p.uppercase(Locale.US)} (PAID)", v, true) }
        cards += Triple("TOTAL TRIP LEGS", d.legs.toDouble(), false)
        cards += Triple("SITES VISITED", d.sites.toDouble(), false)
        if (cards.size < 7) cards += Triple("DAYS", d.days.toDouble(), false)
        s.heights[5] = 22.0
        s.heights[6] = 30.0
        cards.take(7).forEachIndexed { i, (label, value, isAmt) ->
            val c = first + i
            s.set(5, c, label, S_CARD_LABEL)
            s.set(6, c, value, if (isAmt) S_CARD_AMT else S_CARD_VALUE)
        }

        // table
        val header = 8
        s.heights[header] = 22.0
        listOf("Date", "Site", "From", "To", "Amount (OMR)", "Personnel", "Paid By")
            .forEachIndexed { i, h -> s.set(header, first + i, h, S_HEADER) }
        s.freezeRow = header

        var r = header + 1
        d.byDay.forEachIndexed { dayIndex, (date, list) ->
            val z = dayIndex % 2 == 1
            list.forEach { t ->
                s.set(r, 2, t.date.format(ISO), if (z) S_TEXT_C_Z else S_TEXT_C)
                s.set(r, 3, t.site, if (z) S_TEXT_Z else S_TEXT)
                s.set(r, 4, t.from, if (z) S_TEXT_Z else S_TEXT)
                s.set(r, 5, t.to, if (z) S_TEXT_Z else S_TEXT)
                if (t.amount != null) s.set(r, 6, t.amount, if (z) S_AMT_Z else S_AMT)
                else s.set(r, 6, "Included", if (z) S_INCL_Z else S_INCL)
                s.set(r, 7, t.personnel.joinToString(" & "), if (z) S_TEXT_Z else S_TEXT)
                s.set(r, 8, if (t.amount != null) t.paidBy else "", if (z) S_TEXT_C_Z else S_TEXT_C)
                r++
            }
            val dayTotal = list.sumOf { it.amount ?: 0.0 }
            s.merge(r, 2, 5, "${date.format(NICE_DATE)}  —  day total  (${list.size} legs)", S_DAY_LABEL)
            s.set(r, 6, dayTotal, S_DAY_AMT)
            s.merge(r, 7, 8, "", S_DAY_LABEL)
            r++
        }
        s.heights[r] = 24.0
        s.merge(r, 2, 5, "GRAND TOTAL  •  ${d.legs} legs  •  ${d.days} days", S_GRAND_LABEL)
        s.set(r, 6, d.total, S_GRAND_AMT)
        s.merge(r, 7, 8, "", S_GRAND_LABEL)
        r += 2
        s.merge(r, 2, 8, footer(), S_FOOT)
        return s
    }

    private fun summarySheet(d: ReportData): Sheet {
        val s = Sheet("Summary")
        listOf(2.5, 26.0, 14.0, 16.0, 14.0, 4.0).forEachIndexed { i, w -> s.widths[i + 1] = w }
        s.heights[2] = 34.0
        s.merge(2, 2, 5, "Summary", S_TITLE)
        s.merge(3, 2, 5, d.rangeLabel, S_SUBTITLE)

        var r = 5
        // ---- paid by
        s.heights[r] = 20.0
        s.merge(r, 2, 5, "WHO PAID", S_SECTION); r++
        listOf("Person", "Fares paid", "Amount (OMR)", "Share").forEachIndexed { i, h -> s.set(r, 2 + i, h, S_HEADER) }
        r++
        d.paidBy.forEachIndexed { i, (p, v) ->
            val z = i % 2 == 1
            s.set(r, 2, p, if (z) S_TEXT_Z else S_TEXT)
            s.set(r, 3, d.paidCount(p).toDouble(), if (z) S_TEXT_C_Z else S_TEXT_C)
            s.set(r, 4, v, if (z) S_AMT_Z else S_AMT)
            s.set(r, 5, if (d.total > 0) v / d.total else 0.0, if (z) S_PCT_Z else S_PCT)
            r++
        }
        s.set(r, 2, "Total", S_GRAND_LABEL)
        s.set(r, 3, d.paidBy.sumOf { d.paidCount(it.first) }.toDouble(), S_GRAND_C)
        s.set(r, 4, d.total, S_GRAND_AMT)
        s.set(r, 5, "", S_GRAND_LABEL)
        r += 3

        // ---- per site
        s.heights[r] = 20.0
        s.merge(r, 2, 5, "BY SITE", S_SECTION); r++
        listOf("Site", "Legs", "Amount (OMR)", "Share").forEachIndexed { i, h -> s.set(r, 2 + i, h, S_HEADER) }
        r++
        d.bySite.forEachIndexed { i, (site, legs, amt) ->
            val z = i % 2 == 1
            s.set(r, 2, site, if (z) S_TEXT_Z else S_TEXT)
            s.set(r, 3, legs.toDouble(), if (z) S_TEXT_C_Z else S_TEXT_C)
            s.set(r, 4, amt, if (z) S_AMT_Z else S_AMT)
            s.set(r, 5, if (d.total > 0) amt / d.total else 0.0, if (z) S_PCT_Z else S_PCT)
            r++
        }
        r += 2

        // ---- per day
        s.heights[r] = 20.0
        s.merge(r, 2, 5, "BY DAY", S_SECTION); r++
        listOf("Date", "Legs", "Amount (OMR)", "Sites").forEachIndexed { i, h -> s.set(r, 2 + i, h, S_HEADER) }
        r++
        d.byDay.forEachIndexed { i, (date, list) ->
            val z = i % 2 == 1
            s.set(r, 2, date.format(NICE_DATE), if (z) S_TEXT_Z else S_TEXT)
            s.set(r, 3, list.size.toDouble(), if (z) S_TEXT_C_Z else S_TEXT_C)
            s.set(r, 4, list.sumOf { it.amount ?: 0.0 }, if (z) S_AMT_Z else S_AMT)
            s.set(r, 5, list.map { it.site }.distinct().size.toDouble(), if (z) S_TEXT_C_Z else S_TEXT_C)
            r++
        }
        r += 2

        // ---- travelled
        s.heights[r] = 20.0
        s.merge(r, 2, 5, "LEGS TRAVELLED PER PERSON", S_SECTION); r++
        s.set(r, 2, "Person", S_HEADER); s.set(r, 3, "Legs", S_HEADER)
        r++
        d.travelled.forEachIndexed { i, (p, n) ->
            val z = i % 2 == 1
            s.set(r, 2, p, if (z) S_TEXT_Z else S_TEXT)
            s.set(r, 3, n.toDouble(), if (z) S_TEXT_C_Z else S_TEXT_C)
            r++
        }
        r += 2
        s.merge(r, 2, 5, footer(), S_FOOT)
        return s
    }

    private fun footer() = "Generated by Taxi Log on " +
        LocalDateTime.now().format(DateTimeFormatter.ofPattern("d MMM yyyy, h:mm a", Locale.US))

    // ------------------------------------------------------------------ xml

    private fun sheetXml(s: Sheet): String = buildString {
        append("""<?xml version="1.0" encoding="UTF-8" standalone="yes"?>""")
        append("""<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">""")
        append("""<sheetPr><pageSetUpPr fitToPage="1"/></sheetPr>""")
        append("""<sheetViews><sheetView workbookViewId="0" showGridLines="0">""")
        if (s.freezeRow > 0) {
            append("""<pane ySplit="${s.freezeRow}" topLeftCell="A${s.freezeRow + 1}" activePane="bottomLeft" state="frozen"/>""")
        }
        append("</sheetView></sheetViews>")
        append("""<sheetFormatPr defaultRowHeight="18" customHeight="1"/>""")
        append("<cols>")
        s.widths.forEach { (c, w) -> append("""<col min="$c" max="$c" width="$w" customWidth="1"/>""") }
        append("</cols><sheetData>")
        val allRows = (s.rows.keys + s.heights.keys).toSortedSet()
        for (r in allRows) {
            val h = s.heights[r] ?: 18.0
            append("""<row r="$r" ht="$h" customHeight="1">""")
            s.rows[r]?.forEach { (c, cell) ->
                val rf = ref(r, c)
                when (val v = cell.v) {
                    null -> append("""<c r="$rf" s="${cell.s}"/>""")
                    is Number -> append("""<c r="$rf" s="${cell.s}"><v>${Math.round(v.toDouble() * 1_000_000.0) / 1_000_000.0}</v></c>""")
                    else -> append("""<c r="$rf" s="${cell.s}" t="inlineStr"><is><t xml:space="preserve">${esc(v.toString())}</t></is></c>""")
                }
            }
            append("</row>")
        }
        append("</sheetData>")
        if (s.merges.isNotEmpty()) {
            append("""<mergeCells count="${s.merges.size}">""")
            s.merges.forEach { append("""<mergeCell ref="$it"/>""") }
            append("</mergeCells>")
        }
        append("""<pageMargins left="0.4" right="0.4" top="0.5" bottom="0.5" header="0.3" footer="0.3"/>""")
        append("""<pageSetup paperSize="9" orientation="portrait" fitToWidth="1" fitToHeight="0"/>""")
        append("</worksheet>")
    }

    private fun contentTypes(n: Int) = buildString {
        append("""<?xml version="1.0" encoding="UTF-8" standalone="yes"?>""")
        append("""<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">""")
        append("""<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>""")
        append("""<Default Extension="xml" ContentType="application/xml"/>""")
        append("""<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>""")
        append("""<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>""")
        for (i in 1..n) append("""<Override PartName="/xl/worksheets/sheet$i.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>""")
        append("</Types>")
    }

    private const val ROOT_RELS = """<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>"""

    private fun workbook(sheets: List<Sheet>) = buildString {
        append("""<?xml version="1.0" encoding="UTF-8" standalone="yes"?>""")
        append("""<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>""")
        sheets.forEachIndexed { i, s -> append("""<sheet name="${esc(s.name)}" sheetId="${i + 1}" r:id="rId${i + 1}"/>""") }
        append("</sheets></workbook>")
    }

    private fun workbookRels(n: Int) = buildString {
        append("""<?xml version="1.0" encoding="UTF-8" standalone="yes"?>""")
        append("""<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">""")
        for (i in 1..n) append("""<Relationship Id="rId$i" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet$i.xml"/>""")
        append("""<Relationship Id="rId${n + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>""")
        append("</Relationships>")
    }

    private fun font(b: Boolean, i: Boolean, sz: Int, color: String) =
        "<font>${if (b) "<b/>" else ""}${if (i) "<i/>" else ""}<sz val=\"$sz\"/><color rgb=\"$color\"/><name val=\"Calibri\"/><family val=\"2\"/></font>"

    private fun fill(color: String) =
        "<fill><patternFill patternType=\"solid\"><fgColor rgb=\"$color\"/><bgColor indexed=\"64\"/></patternFill></fill>"

    private fun xf(numFmt: Int, font: Int, fill: Int, border: Int, h: String = "left", wrap: Boolean = false) =
        "<xf numFmtId=\"$numFmt\" fontId=\"$font\" fillId=\"$fill\" borderId=\"$border\" xfId=\"0\" applyNumberFormat=\"1\" applyFont=\"1\" applyFill=\"1\" applyBorder=\"1\" applyAlignment=\"1\">" +
            "<alignment horizontal=\"$h\" vertical=\"center\"${if (wrap) " wrapText=\"1\"" else ""} indent=\"${if (h == "left") 1 else 0}\"/></xf>"

    private val STYLES: String = run {
        val navy = "FF1F3A5F"
        val fonts = listOf(
            font(false, false, 11, "FF1F2937"), // 0 body
            font(true, false, 11, "FFFFFFFF"),  // 1 header white
            font(true, false, 20, navy),        // 2 title
            font(false, true, 10, "FF6B7280"),  // 3 subtitle / included
            font(true, false, 11, "FF1F2937"),  // 4 bold body
            font(true, false, 15, navy),        // 5 card value
            font(true, false, 8, "FF64748B"),   // 6 card label
            font(true, false, 12, navy),        // 7 section
        )
        val fills = listOf(
            "<fill><patternFill patternType=\"none\"/></fill>",
            "<fill><patternFill patternType=\"gray125\"/></fill>",
            fill(navy),        // 2 header
            fill("FFF3F6FA"),  // 3 zebra
            fill("FFE8F0FE"),  // 4 card
            fill("FFFFF4E5"),  // 5 day total
        )
        val line = "style=\"thin\"><color rgb=\"FFD0D7E2\"/>"
        val borders = listOf(
            "<border><left/><right/><top/><bottom/><diagonal/></border>",
            "<border><left $line</left><right $line</right><top $line</top><bottom $line</bottom><diagonal/></border>",
            "<border><left/><right/><top/><bottom style=\"medium\"><color rgb=\"$navy\"/></bottom><diagonal/></border>",
        )
        val amt = 164
        val pct = 10 // built-in 0.00%
        val xfs = listOf(
            "<xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\"/>", // 0
            xf(0, 2, 0, 0),                    // 1 title
            xf(0, 3, 0, 0),                    // 2 subtitle
            xf(0, 1, 2, 1, "center", true),    // 3 header
            xf(0, 0, 0, 1),                    // 4 text
            xf(0, 0, 3, 1),                    // 5 text zebra
            xf(amt, 0, 0, 1, "right"),         // 6 amount
            xf(amt, 0, 3, 1, "right"),         // 7 amount zebra
            xf(0, 6, 4, 1, "center", true),    // 8 card label
            xf(1, 5, 4, 1, "center"),          // 9 card value (integer)
            xf(amt, 5, 4, 1, "center"),        // 10 card amount
            xf(0, 4, 5, 1),                    // 11 day label
            xf(amt, 4, 5, 1, "right"),         // 12 day amount
            xf(0, 1, 2, 1),                    // 13 grand label
            xf(amt, 1, 2, 1, "right"),         // 14 grand amount
            xf(0, 3, 0, 1, "center"),          // 15 included
            xf(0, 3, 3, 1, "center"),          // 16 included zebra
            xf(0, 7, 0, 2),                    // 17 section
            xf(1, 0, 0, 1, "center"),          // 18 text centered (also ints)
            xf(1, 0, 3, 1, "center"),          // 19 text centered zebra
            xf(pct, 0, 0, 1, "right"),         // 20 percent
            xf(pct, 0, 3, 1, "right"),         // 21 percent zebra
            xf(0, 3, 0, 0),                    // 22 footer
            xf(1, 1, 2, 1, "center"),          // 23 grand centered
        )
        buildString {
            append("""<?xml version="1.0" encoding="UTF-8" standalone="yes"?>""")
            append("""<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">""")
            append("""<numFmts count="1"><numFmt numFmtId="$amt" formatCode="0.000&quot; OMR&quot;"/></numFmts>""")
            append("""<fonts count="${fonts.size}">${fonts.joinToString("")}</fonts>""")
            append("""<fills count="${fills.size}">${fills.joinToString("")}</fills>""")
            append("""<borders count="${borders.size}">${borders.joinToString("")}</borders>""")
            append("""<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>""")
            append("""<cellXfs count="${xfs.size}">${xfs.joinToString("")}</cellXfs>""")
            append("""<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>""")
            append("</styleSheet>")
        }
    }
}
